('za','/flags/history/za-1928.svg','1928-05-31'::date,'1994-04-20'::date,'Flag of South Africa (1928–1994, dark colors)','Drapeau (1928–1994)','Source: Wikimedia Commons (Public domain — Parliament of South Africa (Vector graphics image by Denelson83)). https://commons.wikimedia.org/wiki/File:Flag_of_South_Africa_(1928–1994,_dark_colors).svg','Source : Wikimedia Commons (Public domain — Parliament of South Africa (Vector graphics image by Denelson83)). https://commons.wikimedia.org/wiki/File:Flag_of_South_Africa_(1928–1994,_dark_colors).svg')
) v(iso, img, ds, de, le, lf, ne, nf)
where not exists (
  select 1 from country_flag_history h
  where h.iso_code = v.iso
    and h.date_start is not null
    and abs(extract(year from h.date_start) - extract(year from v.ds)) <= 1
    and abs(coalesce(extract(year from h.date_end), 9999) - extract(year from v.de)) <= 1);